-- Actual manual custody/location observations; no inventory allocation or movements.
CREATE TABLE inventory_reserved_roots(id TEXT PRIMARY KEY,receipt_id TEXT NOT NULL REFERENCES purchase_receipts(id),reservation_id TEXT NOT NULL REFERENCES inventory_order_events(id),order_position INTEGER NOT NULL CHECK(order_position BETWEEN 1 AND 999),store_id TEXT NOT NULL REFERENCES stores(id),serial INTEGER NOT NULL CHECK(serial>0),custody_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(store_id,custody_number));
CREATE TABLE inventory_reserved_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES inventory_reserved_roots(id),store_id TEXT NOT NULL REFERENCES stores(id),version INTEGER NOT NULL CHECK(version>0),base_sequence INTEGER NOT NULL CHECK(base_sequence>=0),receipt_version_id TEXT NOT NULL REFERENCES purchase_receipt_versions(id),receipt_sequence INTEGER NOT NULL CHECK(receipt_sequence>=0),stock_sequence INTEGER NOT NULL CHECK(stock_sequence>0),outbound_revision INTEGER NOT NULL CHECK(outbound_revision>=0),product_return_revision INTEGER NOT NULL CHECK(product_return_revision>=0),observed_at TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 1000000),bucket TEXT NOT NULL CHECK(bucket='reserved'),identity_source TEXT NOT NULL,location_label TEXT NOT NULL,location_source TEXT NOT NULL,source_reference TEXT NOT NULL,note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,version));
CREATE TABLE inventory_reserved_events(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES inventory_reserved_roots(id),version_id TEXT NOT NULL REFERENCES inventory_reserved_versions(id),store_id TEXT NOT NULL REFERENCES stores(id),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('observe','withdraw')),status TEXT NOT NULL CHECK(status IN('recorded','withdrawn')),reason TEXT NOT NULL,next_step TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(root_id,revision),UNIQUE(store_id,sequence));
CREATE VIEW inventory_reserved_current AS SELECT * FROM inventory_reserved_events e WHERE revision=(SELECT max(revision) FROM inventory_reserved_events WHERE root_id=e.root_id);
CREATE TRIGGER inventory_reserved_root_source BEFORE INSERT ON inventory_reserved_roots BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM purchase_receipts r JOIN purchase_receipt_current c ON c.receipt_id=r.id WHERE r.id=NEW.receipt_id AND r.store_id=NEW.store_id AND c.status='posted' AND r.bound_quantity>0) OR NEW.serial<>coalesce((SELECT max(serial)+1 FROM inventory_reserved_roots WHERE store_id=NEW.store_id),1) OR NEW.custody_number IS NOT 'RSC-'||replace(substr(NEW.created_at,1,10),'-','')||'-'||printf('%05d',NEW.serial) THEN RAISE(ABORT,'reserved original posted receipt/root') END;
END;
CREATE TRIGGER inventory_reserved_version_source BEFORE INSERT ON inventory_reserved_versions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_reserved_roots c JOIN purchase_receipts r ON r.id=c.receipt_id JOIN purchase_receipt_current e ON e.receipt_id=r.id JOIN inventory_balances b ON b.product_id=r.product_id JOIN inventory_events s ON s.id=(SELECT id FROM inventory_events WHERE product_id=r.product_id ORDER BY sequence DESC LIMIT 1) WHERE c.id=NEW.root_id AND c.store_id=NEW.store_id AND e.status='posted' AND e.version_id=NEW.receipt_version_id AND NEW.stock_sequence=s.sequence AND NEW.quantity<=b.reserved AND NEW.quantity<=r.bound_quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0) AND NEW.observed_at>=(SELECT max(created_at) FROM purchase_receipt_events WHERE receipt_id=r.id AND action='inbound') AND NEW.outbound_revision=coalesce((SELECT max(outbound_revision) FROM inventory_outbounds WHERE product_id=r.product_id),0) AND NEW.product_return_revision=coalesce((SELECT max(product_revision) FROM supplier_return_handoffs WHERE product_id=r.product_id),0)) OR NEW.version<>coalesce((SELECT max(version)+1 FROM inventory_reserved_versions WHERE root_id=NEW.root_id),1) OR NEW.base_sequence<>coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=NEW.store_id),0) OR NEW.receipt_sequence<>coalesce((SELECT max(sequence) FROM purchase_receiving_journal WHERE store_id=NEW.store_id),0) OR length(NEW.observed_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.observed_at) IS NOT NEW.observed_at OR NEW.observed_at>NEW.created_at THEN RAISE(ABORT,'reserved actual source/current capacity/time') END;
END;
CREATE TRIGGER inventory_reserved_event_source BEFORE INSERT ON inventory_reserved_events BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_reserved_roots r JOIN inventory_reserved_versions v ON v.root_id=r.id WHERE r.id=NEW.root_id AND r.store_id=NEW.store_id AND v.id=NEW.version_id) OR NEW.revision<>coalesce((SELECT max(revision)+1 FROM inventory_reserved_events WHERE root_id=NEW.root_id),1) OR NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM inventory_reserved_events WHERE store_id=NEW.store_id),1) OR EXISTS(SELECT 1 FROM inventory_reserved_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR NOT(NEW.action='observe' AND NEW.status='recorded' AND EXISTS(SELECT 1 FROM inventory_reserved_versions v WHERE v.id=NEW.version_id AND v.version=(SELECT coalesce(max(version),0)+1 FROM inventory_reserved_versions WHERE root_id=NEW.root_id AND id<>v.id) AND v.base_sequence+1=NEW.sequence AND v.created_at=NEW.created_at AND v.created_by=NEW.created_by) OR NEW.action='withdraw' AND NEW.status='withdrawn' AND EXISTS(SELECT 1 FROM inventory_reserved_current c WHERE c.root_id=NEW.root_id AND c.status='recorded' AND c.version_id=NEW.version_id)) THEN RAISE(ABORT,'custody explicit paired observation/withdrawal') END;
END;
CREATE TABLE inventory_reserved_stock_context(stock_event_id TEXT PRIMARY KEY REFERENCES inventory_events(id),custody_sequence INTEGER NOT NULL CHECK(custody_sequence>=0));
INSERT INTO inventory_reserved_stock_context SELECT id,0 FROM inventory_events;
CREATE TRIGGER inventory_reserved_stock_context_capture AFTER INSERT ON inventory_events BEGIN INSERT INTO inventory_reserved_stock_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_reserved_stock_context_source BEFORE INSERT ON inventory_reserved_stock_context WHEN NOT EXISTS(SELECT 1 FROM inventory_events e WHERE e.id=NEW.stock_event_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved original context');END;
CREATE TRIGGER inventory_reserved_stock_context_chronology BEFORE INSERT ON inventory_events WHEN EXISTS(SELECT 1 FROM inventory_reserved_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved original chronology');END;
CREATE TABLE inventory_reserved_dispatch_context(outbound_id TEXT PRIMARY KEY REFERENCES inventory_outbounds(id),custody_sequence INTEGER NOT NULL CHECK(custody_sequence>=0));
INSERT INTO inventory_reserved_dispatch_context SELECT id,0 FROM inventory_outbounds;
CREATE TRIGGER inventory_reserved_dispatch_context_capture AFTER INSERT ON inventory_outbounds BEGIN INSERT INTO inventory_reserved_dispatch_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_reserved_dispatch_context_source BEFORE INSERT ON inventory_reserved_dispatch_context WHEN NOT EXISTS(SELECT 1 FROM inventory_outbounds e WHERE e.id=NEW.outbound_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved original context');END;
CREATE TRIGGER inventory_reserved_dispatch_context_chronology BEFORE INSERT ON inventory_outbounds WHEN EXISTS(SELECT 1 FROM inventory_reserved_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved original chronology');END;
