INSERT INTO inventory_reserved_receipt_context SELECT id,0 FROM purchase_receipt_events;
CREATE TRIGGER inventory_reserved_receipt_context_capture AFTER INSERT ON purchase_receipt_events BEGIN INSERT INTO inventory_reserved_receipt_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_reserved_receipt_context_source BEFORE INSERT ON inventory_reserved_receipt_context WHEN NOT EXISTS(SELECT 1 FROM purchase_receipt_events e WHERE e.id=NEW.receipt_event_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved original context');END;
CREATE TRIGGER inventory_reserved_receipt_context_chronology BEFORE INSERT ON purchase_receipt_events WHEN EXISTS(SELECT 1 FROM inventory_reserved_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved original chronology');END;
