INSERT INTO inventory_reserved_return_context SELECT id,0 FROM supplier_return_handoffs;
CREATE TRIGGER inventory_reserved_return_context_capture AFTER INSERT ON supplier_return_handoffs BEGIN INSERT INTO inventory_reserved_return_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_reserved_return_context_source BEFORE INSERT ON inventory_reserved_return_context WHEN NOT EXISTS(SELECT 1 FROM supplier_return_handoffs e WHERE e.id=NEW.handoff_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved original context');END;
CREATE TRIGGER inventory_reserved_return_context_chronology BEFORE INSERT ON supplier_return_handoffs WHEN EXISTS(SELECT 1 FROM inventory_reserved_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved original chronology');END;
CREATE TRIGGER inventory_reserved_roots_actor BEFORE INSERT ON inventory_reserved_roots WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role='manager' AND coalesce(q.must_change_password,0)=0) BEGIN SELECT RAISE(ABORT,'custody actor/time');END;
CREATE TRIGGER inventory_reserved_versions_actor BEFORE INSERT ON inventory_reserved_versions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role='manager' AND coalesce(q.must_change_password,0)=0) BEGIN SELECT RAISE(ABORT,'custody actor/time');END;
CREATE TRIGGER inventory_reserved_versions_text BEFORE INSERT ON inventory_reserved_versions WHEN length(trim(NEW.identity_source)) NOT BETWEEN 1 AND 2000 OR length(NEW.identity_source)>2000 OR length(trim(NEW.location_label)) NOT BETWEEN 1 AND 300 OR length(NEW.location_label)>300 OR length(trim(NEW.location_source)) NOT BETWEEN 1 AND 2000 OR length(NEW.location_source)>2000 OR length(trim(NEW.source_reference)) NOT BETWEEN 1 AND 1000 OR length(NEW.source_reference)>1000 OR length(trim(NEW.note)) NOT BETWEEN 1 AND 2000 OR length(NEW.note)>2000 OR length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 BEGIN SELECT RAISE(ABORT,'reserved actual source text');END;
CREATE TRIGGER inventory_reserved_events_actor BEFORE INSERT ON inventory_reserved_events WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR NEW.created_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security q ON q.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.active=1 AND u.role='manager' AND coalesce(q.must_change_password,0)=0) BEGIN SELECT RAISE(ABORT,'custody actor/time');END;
CREATE TRIGGER inventory_reserved_events_text BEFORE INSERT ON inventory_reserved_events WHEN length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300 OR length(trim(NEW.next_step)) NOT BETWEEN 1 AND 2000 OR length(NEW.next_step)>2000 BEGIN SELECT RAISE(ABORT,'reserved actual source text');END;
CREATE TRIGGER inventory_reserved_roots_no_update BEFORE UPDATE ON inventory_reserved_roots BEGIN SELECT RAISE(ABORT,'reserved immutable');END;
CREATE TRIGGER inventory_reserved_roots_no_delete BEFORE DELETE ON inventory_reserved_roots BEGIN SELECT RAISE(ABORT,'reserved immutable');END;
