CREATE TRIGGER inventory_reserved_receipt_context_no_delete BEFORE DELETE ON inventory_reserved_receipt_context BEGIN SELECT RAISE(ABORT,'reserved immutable');END;
CREATE TRIGGER inventory_reserved_return_context_no_update BEFORE UPDATE ON inventory_reserved_return_context BEGIN SELECT RAISE(ABORT,'reserved immutable');END;
CREATE TRIGGER inventory_reserved_return_context_no_delete BEFORE DELETE ON inventory_reserved_return_context BEGIN SELECT RAISE(ABORT,'reserved immutable');END;
CREATE TRIGGER inventory_reserved_version_time BEFORE INSERT ON inventory_reserved_versions BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM inventory_reserved_roots r JOIN purchase_receipts p ON p.id=r.receipt_id WHERE r.id=NEW.root_id AND (EXISTS(SELECT 1 FROM inventory_events WHERE product_id=p.product_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM inventory_outbounds WHERE product_id=p.product_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM supplier_return_handoffs WHERE product_id=p.product_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM purchase_receiving_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at))) OR EXISTS(SELECT 1 FROM inventory_reserved_versions WHERE root_id=NEW.root_id AND observed_at>NEW.observed_at) OR NEW.version=1 AND NOT EXISTS(SELECT 1 FROM inventory_reserved_roots WHERE id=NEW.root_id AND created_at=NEW.created_at AND created_by=NEW.created_by) THEN RAISE(ABORT,'custody adopted source chronology/root pairing') END;
END;
CREATE TRIGGER inventory_reserved_source_chronology BEFORE INSERT ON inventory_reserved_events WHEN EXISTS(SELECT 1 FROM inventory_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM inventory_outbounds WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM supplier_return_handoffs WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM purchase_receiving_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody whole source chronology');END;
ALTER TABLE inventory_reserved_versions ADD COLUMN quality_sequence INTEGER NOT NULL CHECK(quality_sequence>=0);
CREATE TABLE inventory_reserved_quality_context(quality_event_id TEXT PRIMARY KEY REFERENCES purchase_quality_events(id),custody_sequence INTEGER NOT NULL CHECK(custody_sequence>=0));
INSERT INTO inventory_reserved_quality_context SELECT id,0 FROM purchase_quality_events;
CREATE TRIGGER inventory_reserved_quality_context_capture AFTER INSERT ON purchase_quality_events BEGIN INSERT INTO inventory_reserved_quality_context VALUES(NEW.id,coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=NEW.store_id),0));END;
CREATE TRIGGER inventory_reserved_quality_context_source BEFORE INSERT ON inventory_reserved_quality_context WHEN NOT EXISTS(SELECT 1 FROM purchase_quality_events e WHERE e.id=NEW.quality_event_id AND NEW.custody_sequence=coalesce((SELECT max(sequence) FROM inventory_reserved_events WHERE store_id=e.store_id),0)) BEGIN SELECT RAISE(ABORT,'reserved original quality context');END;
CREATE TRIGGER inventory_reserved_quality_context_chronology BEFORE INSERT ON purchase_quality_events WHEN EXISTS(SELECT 1 FROM inventory_reserved_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved original quality chronology');END;
CREATE TRIGGER inventory_reserved_quality_context_no_update BEFORE UPDATE ON inventory_reserved_quality_context BEGIN SELECT RAISE(ABORT,'reserved immutable');END;
CREATE TRIGGER inventory_reserved_quality_context_no_delete BEFORE DELETE ON inventory_reserved_quality_context BEGIN SELECT RAISE(ABORT,'reserved immutable');END;
CREATE TRIGGER inventory_reserved_quality_source BEFORE INSERT ON inventory_reserved_versions WHEN NEW.quality_sequence<>coalesce((SELECT max(sequence) FROM purchase_quality_journal WHERE store_id=NEW.store_id),0) OR NEW.bucket='reserved' AND NOT EXISTS(SELECT 1 FROM inventory_reserved_roots c JOIN purchase_receipts r ON r.id=c.receipt_id WHERE c.id=NEW.root_id AND NEW.quantity<=r.bound_quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)) OR EXISTS(SELECT 1 FROM purchase_quality_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'custody protected original quality/current source');END;
CREATE TRIGGER inventory_reserved_quality_event_time BEFORE INSERT ON inventory_reserved_events WHEN EXISTS(SELECT 1 FROM purchase_quality_journal WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved original quality chronology');END;

ALTER TABLE inventory_reserved_versions ADD COLUMN batch_sequence INTEGER NOT NULL CHECK(batch_sequence>=0);
ALTER TABLE inventory_reserved_versions ADD COLUMN reservation_revision INTEGER NOT NULL CHECK(reservation_revision>0);
CREATE TRIGGER inventory_reserved_order_source BEFORE INSERT ON inventory_reserved_roots WHEN NOT EXISTS(SELECT 1 FROM inventory_order_events e JOIN inventory_order_lines l ON l.event_id=e.id JOIN purchase_receipts r ON r.id=NEW.receipt_id JOIN retail_product_versions rp ON rp.product_id=r.product_id AND rp.version=r.product_version JOIN retail_product_versions op ON op.product_id=l.product_id AND op.version=l.product_version WHERE e.id=NEW.reservation_id AND e.store_id=NEW.store_id AND l.position=NEW.order_position AND l.product_id=r.product_id AND e.action='reserve' AND e.revision=(SELECT max(revision) FROM inventory_order_events WHERE order_id=e.order_id) AND rp.unit=op.unit AND rp.category=op.category) BEGIN SELECT RAISE(ABORT,'reserved original active order/line/unit');END;
CREATE TRIGGER inventory_reserved_fixed_order_capacity BEFORE INSERT ON inventory_reserved_versions WHEN NOT EXISTS(SELECT 1 FROM inventory_reserved_roots c JOIN inventory_order_events e ON e.id=c.reservation_id JOIN inventory_order_lines l ON l.event_id=e.id AND l.position=c.order_position JOIN purchase_receipts r ON r.id=c.receipt_id WHERE c.id=NEW.root_id AND e.action='reserve' AND e.revision=(SELECT max(revision) FROM inventory_order_events WHERE order_id=e.order_id) AND NEW.reservation_revision=e.revision AND NEW.observed_at>=e.created_at AND NEW.quantity<=l.quantity-coalesce((SELECT sum(quantity) FROM inventory_outbounds WHERE reservation_id=e.id AND position=l.position),0) AND NEW.quantity<=r.bound_quantity-coalesce((SELECT sum(quantity) FROM supplier_return_handoffs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM inventory_batch_refs WHERE receipt_id=r.id),0)-coalesce((SELECT sum(quantity) FROM purchase_quality_holds WHERE receipt_id=r.id),0)) OR NEW.batch_sequence<>coalesce((SELECT max(sequence) FROM inventory_batch_declarations WHERE store_id=NEW.store_id),0) OR EXISTS(SELECT 1 FROM inventory_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved fixed actual remaining original capacity/source');END;
