CREATE TRIGGER inventory_reserved_all_source_chronology BEFORE INSERT ON inventory_reserved_events WHEN EXISTS(SELECT 1 FROM inventory_order_events WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM inventory_batch_declarations WHERE store_id=NEW.store_id AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'reserved all original source chronology');END;
